<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verifikasi Student ID | MARI</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f2f1e9;font-family:Arial,sans-serif;color:#22251f}.verify{max-width:520px;margin:9vh auto;background:#fffef8;border:1px solid #e1e1d7;border-radius:18px;padding:35px;text-align:center}.mark{width:64px;height:64px;border-radius:50%;display:grid;place-items:center;margin:auto auto 18px;font-size:28px;background:{{ $valid ? '#d3ff70' : '#ffd9d4' }}}</style></head><body><div class="verify"><div class="fw-bold fs-3 mb-4">MARI<span style="color:#9bc63d">.</span></div><div class="mark">{{ $valid ? '✓' : '!' }}</div><h2 class="fw-bold">{{ $valid ? 'Identitas Terverifikasi' : 'Identitas Tidak Valid' }}</h2><p class="text-secondary">{{ $valid ? 'Data kartu mahasiswa ditemukan dalam sistem MARI.' : 'Kartu tidak ditemukan atau status mahasiswa tidak aktif.' }}</p>@if($user && $valid)<hr>@if($user->profile_visibility === 'public')<h4 class="fw-bold">{{ $user->name }}</h4><div>{{ $user->nim }}</div><div class="text-secondary mt-1">{{ $user->program_study }}</div>@else<div class="text-secondary">Profil diatur privat. Kartu mahasiswa ini tetap valid.</div>@endif<span class="badge text-bg-success mt-3">ACTIVE STUDENT</span>@endif<div class="small text-secondary mt-4">MARI Student Portal · {{ now()->format('d/m/Y H:i') }}</div></div></body></html>
